// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.36;
contract C {
    uint256 public sequence;
    function next(uint256 value) internal returns (uint256) { sequence += 1; return value + sequence; }
    error X(uint256 a, uint256 b);
    error Mixed(uint256 a, string b, address c);
    function effects(bool ok) external { uint256 b = next(60); uint256 a = next(50); require(ok, X(a, b)); }
    function f() external pure { require(false, X(1, 2)); }
    function values(bool ok, uint256 x, uint256 y) external pure { require(ok, X(x, y)); }
    function mixed(bool ok, uint256 x, string calldata y, address z) external pure { require(ok, Mixed(x, y, z)); }
}
